mapper.select:
SELECT s.student_no, s.name, CASE s.gender WHEN 1 THEN '男' ELSE '女' END as gender_str, s.college_name, s.major_name, s.class_name, s.bed_number, s.emergency_contact, s.emergency_phone, s.room_id, s.building_id, s.counselor_id, u.phone as user_phone, b.name as building_name, r.room_number, c.name as counselor_name, c.phone as counselor_phone
FROM tb_student s LEFT JOIN sys_user u ON s.student_id = u.user_id LEFT JOIN tb_building b ON s.building_id = b.building_id LEFT JOIN tb_room r ON s.room_id = r.room_id LEFT JOIN tb_counselor c ON s.counselor_id = c.counselor_id
WHERE s.student_id = #{userId}

mapper.update:
UPDATE tb_student
SET
    emergency_contact = #{contact},
    emergency_phone = #{phone}
WHERE student_id = #{studentId}
